args.command:
py -c "import subprocess,csv,io,re; out=subprocess.check_output(['tasklist','/FO','CSV','/NH'],text=True,encoding='utf-8',errors='ignore'); rows=[]
for r in csv.reader(io.StringIO(out)):
    if len(r)>=5:
        mem=int(re.sub(r'[^0-9]','',r[4]) or 0); rows.append((mem,r[0],r[1]))
for mem,name,pid in sorted(rows, reverse=True)[:3]: print(f'{name}\t{pid}\t{mem/1024:.1f}')"

args.content:
$dl = Join-Path $env:USERPROFILE 'Downloads'
$map = [ordered]@{
  'Installers' = @('.exe','.msi','.dmg')
  'Videos'     = @('.mp4','.mov','.mkv','.avi')
  'Images'     = @('.png','.jpg','.jpeg','.webp','.gif')
  'Audio'      = @('.mp3','.wav','.m4a')
  'Documents'  = @('.pdf','.txt','.html','.doc','.docx','.xls','.xlsx','.ppt','.pptx')
  'Archives'   = @('.zip','.rar','.7z')
  'Scripts'    = @('.js','.ps1','.py')
  'System'     = @('.winmd')
}

foreach ($folder in $map.Keys) {
  New-Item -ItemType Directory -Path (Join-Path $dl $folder) -Force | Out-Null
}

$moved = @()
Get-ChildItem -LiteralPath $dl -Force -File | Where-Object { $_.Name -ne 'desktop.ini' } | ForEach-Object {
  $file = $_
  $targetFolder = $null
  foreach ($folder in $map.Keys) {
    if ($map[$folder] -contains $file.Extension.ToLowerInvariant()) {
      $targetFolder = Join-Path $dl $folder
      break
    }
  }
  if (-not $targetFolder) {
    $targetFolder = Join-Path $dl 'Misc'
    New-Item -ItemType Directory -Path $targetFolder -Force | Out-Null
  }

  $dest = Join-Path $targetFolder $file.Name
  if (Test-Path -LiteralPath $dest) {
    $base = [IO.Path]::GetFileNameWithoutExtension($file.Name)
    $ext = $file.Extension
    $i = 1
    do {
      $dest = Join-Path $targetFolder ("{0} ({1}){2}" -f $base, $i, $ext)
      $i++
    } while (Test-Path -LiteralPath $dest)
  }

  Move-Item -LiteralPath $file.FullName -Destination $dest
  $moved += [pscustomobject]@{ Name = $file.Name; To = (Split-Path $targetFolder -Leaf) }
}

$keptFolders = Get-ChildItem -LiteralPath $dl -Force -Directory |
  Where-Object { $_.Name -notin @('Ava','Installers','Videos','Images','Audio','Documents','Archives','Scripts','System','Misc') } |
  Select-Object -ExpandProperty Name

Write-Output "Moved $($moved.Count) files into category folders."
$moved | Group-Object To | Sort-Object Name | ForEach-Object { Write-Output "$($_.Name): $($_.Count)" }
if ($keptFolders) { Write-Output "Left existing folders alone: $($keptFolders -join ', ')" }
